const bin = $input.item.binary?.data;
if (!bin) throw new Error('No binary data on item — Telegram Get File did not download');
// n8n stores binary either inline (bin.data is base64) or on disk (filesystem-v2:
// bin.data is the literal string "filesystem-v2" and the real bytes are on disk).
// In filesystem mode, decoding bin.data as base64 gives 9 bogus bytes — always
// prefer bin.bytes when it's a valid number.
let byteLength;
if (typeof bin.bytes === 'number' && bin.bytes > 0) {
  byteLength = bin.bytes;
} else {
  const b64 = bin.data || '';
  byteLength = Buffer.byteLength(b64, 'base64');
}
if (!byteLength) throw new Error('Could not determine binary byte length — bin.bytes missing and bin.data not base64');
return {
  json: { ...$input.item.json, file_byte_length: byteLength, file_mime_type: bin.mimeType || 'video/mp4' },
  binary: $input.item.binary
};

const raw = $input.item.json;
const text = raw?.candidates?.[0]?.content?.parts?.[0]?.text
  ?? raw?.content?.parts?.[0]?.text
  ?? '';
const finishReason = raw?.candidates?.[0]?.finishReason || 'UNKNOWN';

function stripFences(s){ return s.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```\s*$/,'').trim(); }
function repair(s){ return s.replace(/,(\s*[}\]])/g,'$1').replace(/[\u201C\u201D]/g,'"').replace(/[\u2018\u2019]/g,"'"); }

let parsed = null;
let mode = 'none';
const cleaned = stripFences(text);

try { parsed = JSON.parse(cleaned); mode = 'strict'; } catch (_) {}
if (!parsed) { try { parsed = JSON.parse(repair(cleaned)); mode = 'repaired'; } catch (_) {} }
if (!parsed) {
  const firstBrace = cleaned.indexOf('{');
  if (firstBrace >= 0) {
    let depth = 0, inStr = false, esc = false, end = -1;
    for (let i = firstBrace; i < cleaned.length; i++) {
      const c = cleaned[i];
      if (esc) { esc = false; continue; }
      if (c === '\\' && inStr) { esc = true; continue; }
      if (c === '"') { inStr = !inStr; continue; }
      if (inStr) continue;
      if (c === '{') depth++;
      else if (c === '}') { depth--; if (depth === 0) { end = i; break; } }
    }
    if (end > 0) {
      const slice = cleaned.slice(firstBrace, end + 1);
      try { parsed = JSON.parse(slice); mode = 'recovered'; } catch (_) {}
      if (!parsed) { try { parsed = JSON.parse(repair(slice)); mode = 'recovered+repaired'; } catch (_) {} }
    }
  }
}

if (!parsed) {
  throw new Error('Could not parse Gemini analysis JSON. finishReason=' + finishReason + ' text starts with: ' + text.slice(0, 120));
}

return {
  json: {
    transcript: String(parsed.transcript || ''),
    description: String(parsed.description || ''),
    raw_text: text,
    parse_mode: mode,
    finish_reason: finishReason
  }
};

