const createDoc = $input.item.json;
const md = String($('Narrative Agent').first()?.json?.output || '');
const rawTranscript = String($('Parse Analysis').first()?.json?.transcript || '').trim();

function cleanMarkdown(src) {
  const lines = src.split('\n');
  const out = [];
  let prev = '';
  for (let raw of lines) {
    let line = raw;
    let m;
    if ((m = line.match(/^#\s+(.+?)\s*$/))) {
      if (out.length && prev !== '') out.push('');
      out.push(m[1].toUpperCase());
      out.push('');
      prev = '';
      continue;
    }
    if ((m = line.match(/^(##|###)\s+(.+?)\s*$/))) {
      if (out.length && prev !== '') out.push('');
      out.push(m[2]);
      prev = m[2];
      continue;
    }
    line = line.replace(/^(\s*)[-*+]\s+/, '$1\u2022 ');
    line = line.replace(/\*\*(.+?)\*\*/g, '$1');
    line = line.replace(/__([^_\n]+)__/g, '$1');
    line = line.replace(/(^|[^*])\*([^*\n]+)\*(?!\*)/g, '$1$2');
    line = line.replace(/(^|[^_])_([^_\n]+)_(?!_)/g, '$1$2');
    line = line.replace(/`([^`]+)`/g, '$1');
    line = line.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1 ($2)');
    line = line.replace(/^\s*>\s?/, '');
    line = line.replace(/^#+\s*/, '');
    out.push(line);
    prev = line;
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trim();
}

function formatTranscript(raw) {
  if (!raw) return '';
  let t = raw.replace(/\*\*(.+?)\*\*/g, '$1').replace(/__([^_\n]+)__/g, '$1');
  t = t.replace(/\r\n/g, '\n');
  const lines = t.split('\n').map(l => l.trim()).filter(Boolean);
  if (lines.length > 1) return lines.join('\n\n');
  let single = lines[0] || '';
  single = single.replace(/\s+(?=\[\d{1,2}:\d{2}\])/g, '\n\n');
  single = single.replace(/([.?!"\]\)])\s+(?=[A-Z][A-Za-z0-9 '()&.-]{0,40}:\s)/g, '$1\n\n');
  return single.replace(/\n{3,}/g, '\n\n').trim();
}

const narrative = cleanMarkdown(md);
const transcriptBlock = rawTranscript
  ? '\n\nTranscript\n' + formatTranscript(rawTranscript)
  : '\n\nTranscript\n(no speech detected)';

return {
  json: {
    id: createDoc.id,
    doc_name: createDoc.name,
    clean_text: narrative + transcriptBlock + '\n'
  }
};

const safeGet = (name) => { try { return $(name).first()?.json; } catch (e) { return null; } };
const doc = safeGet('Create Google Doc') || {};
const analysis = safeGet('Parse Analysis') || {};
const narrative = safeGet('Narrative Agent') || {};
const parseIn = safeGet('Parse Input') || {};

const docUrl = doc.id ? ('https://docs.google.com/document/d/' + doc.id + '/edit') : '';
const markdown = String(narrative.output || '');

let title = 'Video Analysis';
const titleMatch = markdown.match(/^#\s+(.+?)\s*$/m);
if (titleMatch) title = titleMatch[1].trim();

let summary = '';
const summaryMatch = markdown.match(/##\s+Summary\s*\n+([\s\S]*?)(?=\n##\s|$)/i);
if (summaryMatch) summary = summaryMatch[1].trim();
if (!summary) summary = String(analysis.description || '').slice(0, 500);

let keyMoments = [];
const kmMatch = markdown.match(/##\s+Key moments\s*\n+([\s\S]*?)(?=\n##\s|$)/i);
if (kmMatch) {
  keyMoments = kmMatch[1]
    .split('\n')
    .map(l => l.replace(/^\s*[-*+\u2022]\s*/, '').replace(/\*\*(.+?)\*\*/g, '$1').replace(/[_`]/g, '').trim())
    .filter(Boolean)
    .slice(0, 6);
}

const transcript = String(analysis.transcript || '');
const transcriptLines = transcript.split('\n').filter(l => l.trim()).length;
const actionLines = (transcript.match(/\[\d{1,2}:\d{2}\]\s*ACTION:/gi) || []).length;
const dialogueLines = (transcript.match(/\[\d{1,2}:\d{2}\]\s+(?!ACTION:|SFX:|TEXT ON SCREEN:|MUSIC:|NARRATION:)[A-Z][A-Za-z0-9 '()&.-]{0,40}:\s/g) || []).length;
const lastTimestampMatch = transcript.match(/\[(\d{1,2}):(\d{2})\][^\[]*$/);
let runtime = '';
if (lastTimestampMatch) runtime = `${lastTimestampMatch[1]}:${lastTimestampMatch[2]}`;

const escapeMd = (s) => String(s).replace(/([_*`\[\]])/g, '\\$1');
const lines = [];
lines.push('*' + escapeMd(title) + '*');
lines.push('');
lines.push(summary.slice(0, 700));
if (keyMoments.length) {
  lines.push('');
  lines.push('*Key moments:*');
  for (const m of keyMoments) lines.push('\u2022 ' + m.slice(0, 220));
}

const stats = [];
if (runtime) stats.push(runtime + ' runtime');
if (dialogueLines) stats.push(dialogueLines + ' dialogue line' + (dialogueLines === 1 ? '' : 's'));
if (actionLines) stats.push(actionLines + ' action beat' + (actionLines === 1 ? '' : 's'));
if (!dialogueLines && !actionLines && transcriptLines) stats.push(transcriptLines + ' transcript lines');
if (stats.length) {
  lines.push('');
  lines.push('_' + stats.join(' \u00b7 ') + '_');
}

lines.push('');
if (docUrl) lines.push('Full write-up: [Open Google Doc](' + docUrl + ')');

const message_text = lines.join('\n').slice(0, 3800);
const reply_markup = docUrl
  ? { inline_keyboard: [[{ text: 'Open analysis', url: docUrl }]] }
  : undefined;

return [{ json: {
  message_text,
  reply_markup: reply_markup ? JSON.stringify(reply_markup) : '',
  telegram_chat_id: parseIn.telegram_chat_id,
  doc_url: docUrl
} }];
